            fx = 60.0 * (5.0 - x) - 30.0 * vxd  # Stronger forward thrust
            fy = 100.0 * (ty - y) - 50.0 * vyd + w_comp  # Strong upward force to clear wall
        else:
            # Normal forward force when not near the wall
            fx = 40.0 * (5.0 - x) - 20.0 * vxd
            fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp

        # Check if in activation zone and velocity is low enough for 5 consecutive steps
        if (cfg["act_lo"] <= x <= cfg["act_hi"]) and (abs(vxd) < VELOCITY_THRESHOLD):
            state["unlock_steps"] += 1
            if state["unlock_steps"] >= STEP_THRESHOLD:
                state["phase"] = "UNLOCK"
                state["t"] = 0
        else:
            state["unlock_steps"] = 0

    elif state["phase"] == "UNLOCK":
        vx_p, vy_p = sandbox.get_agent_velocity()
        spd = math.hypot(vx_p, vy_p)
        fx_cmd = -35.0  # Strictly less than -34.0 N
        fy_cmd = 50.0 * (ty - y) - 20.0 * vyd + w_comp

        # Adjust forces based on velocity to stabilize and decelerate
        if spd >= cfg["bspd"] * 0.99:
            # Apply deceleration to meet unlock velocity requirement
            fx_cmd += -1.5 * vx_p
            fy_cmd -= 1.5 * vy_p

        fx, fy = fx_cmd, fy_cmd
        state["t"] += 1

        # Immediately transition to ESCAPE after unlock
        if state["t"] >= 1:
            state["phase"] = "ESCAPE"
            state["t"] = 0

    elif state["phase"] == "ESCAPE":
        # Apply strong forward force to move past initial wall and navigate maze
        fx = ESCAPE_FORCE
        fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp

        # Check if in exit zone
        if x >= _exit_x_min(sandbox):
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        fx, fy = 0.0, w_comp

    sandbox.apply_agent_force(fx, fy)
